package com.minenorth_eurobank.braquage.network;
import com.minenorth_eurobank.EuroBank; import com.minenorth_eurobank.braquage.bank.MainBankManager; import com.minenorth_eurobank.braquage.client.ClientNetworkHandler; import net.minecraft.network.FriendlyByteBuf; import net.minecraft.resources.ResourceLocation; import net.minecraft.server.level.ServerPlayer; import net.minecraftforge.api.distmarker.Dist; import net.minecraftforge.network.NetworkEvent; import net.minecraftforge.network.NetworkRegistry; import net.minecraftforge.network.PacketDistributor; import net.minecraftforge.network.simple.SimpleChannel; import net.minecraftforge.fml.DistExecutor; import java.util.*; import java.util.function.Supplier;
public final class ModNetwork{private ModNetwork(){} private static final String PROTOCOL="1"; public static final SimpleChannel CHANNEL=NetworkRegistry.newSimpleChannel(new ResourceLocation(EuroBank.MODID,"network"),()->PROTOCOL,PROTOCOL::equals,PROTOCOL::equals);private static int id=0; public static void register(){CHANNEL.registerMessage(id++,OpenHackPacket.class,OpenHackPacket::encode,OpenHackPacket::decode,OpenHackPacket::handle);CHANNEL.registerMessage(id++,HackClickPacket.class,HackClickPacket::encode,HackClickPacket::decode,HackClickPacket::handle);CHANNEL.registerMessage(id++,CloseHackPacket.class,CloseHackPacket::encode,CloseHackPacket::decode,CloseHackPacket::handle);CHANNEL.registerMessage(id++,HackProgressPacket.class,HackProgressPacket::encode,HackProgressPacket::decode,HackProgressPacket::handle);} public static void sendOpenHack(ServerPlayer p,List<Integer>s){CHANNEL.send(PacketDistributor.PLAYER.with(()->p),new OpenHackPacket(s));} public static void sendCloseHack(ServerPlayer p){CHANNEL.send(PacketDistributor.PLAYER.with(()->p),new CloseHackPacket());} public static void sendHackProgress(ServerPlayer p,int i,int t){CHANNEL.send(PacketDistributor.PLAYER.with(()->p),new HackProgressPacket(i,t));}
public record OpenHackPacket(List<Integer> sequence){static void encode(OpenHackPacket p,FriendlyByteBuf b){b.writeVarInt(p.sequence.size());p.sequence.forEach(b::writeVarInt);}static OpenHackPacket decode(FriendlyByteBuf b){int n=b.readVarInt();var s=new ArrayList<Integer>();for(int i=0;i<n;i++)s.add(b.readVarInt());return new OpenHackPacket(s);}static void handle(OpenHackPacket p,Supplier<NetworkEvent.Context> c){c.get().enqueueWork(()->DistExecutor.unsafeRunWhenOn(Dist.CLIENT,()->()->ClientNetworkHandler.openHack(p.sequence)));c.get().setPacketHandled(true);}}
public record HackClickPacket(int cell){static void encode(HackClickPacket p,FriendlyByteBuf b){b.writeVarInt(p.cell);}static HackClickPacket decode(FriendlyByteBuf b){return new HackClickPacket(b.readVarInt());}static void handle(HackClickPacket p,Supplier<NetworkEvent.Context> c){c.get().enqueueWork(()->{if(c.get().getSender()!=null)MainBankManager.click(c.get().getSender(),p.cell);});c.get().setPacketHandled(true);}}
public record CloseHackPacket(){static void encode(CloseHackPacket p,FriendlyByteBuf b){}static CloseHackPacket decode(FriendlyByteBuf b){return new CloseHackPacket();}static void handle(CloseHackPacket p,Supplier<NetworkEvent.Context> c){c.get().enqueueWork(()->{if(c.get().getSender()!=null)MainBankManager.cancel(c.get().getSender().getUUID());DistExecutor.unsafeRunWhenOn(Dist.CLIENT,()->()->ClientNetworkHandler.closeHack());});c.get().setPacketHandled(true);}}
public record HackProgressPacket(int index,int total){static void encode(HackProgressPacket p,FriendlyByteBuf b){b.writeVarInt(p.index);b.writeVarInt(p.total);}static HackProgressPacket decode(FriendlyByteBuf b){return new HackProgressPacket(b.readVarInt(),b.readVarInt());}static void handle(HackProgressPacket p,Supplier<NetworkEvent.Context> c){c.get().enqueueWork(()->DistExecutor.unsafeRunWhenOn(Dist.CLIENT,()->()->ClientNetworkHandler.setProgress(p.index,p.total)));c.get().setPacketHandled(true);}}}
